def render_body(rows):
    seqids = set()
    for row in rows:
        seqid = row.get("seqid") or row.get("somamer") or row.get("protein") or ""
        if seqid:
            seqids.add(seqid)
    items = []
    for organ, proteins in ORGAN_PROTEINS.items():
        needed = set(proteins)
        if needed and needed <= seqids:
            items.append(
                {
                    "name": DISPLAY[organ],
                    "aliases": [DISPLAY[organ], organ],
                    "detail": f"{organ} 的 {len(needed)} 个模型蛋白都在你的表里。这只表示通过了齐套门槛，不是器官年龄。",
                }
            )
    if items:
        sentence = "这次只标出模型蛋白已经到齐的器官，没有计算器官年龄。"
    elif seqids:
        sentence = "这次检查了蛋白是否齐套，没有哪个器官到齐。"
    else:
        sentence = "没有提供蛋白序列号，这次没有检查齐套。"
    return ["# 器官蛋白齐套", "", sentence], items


def fixture_rows():
    rows = [{"seqid": seqid} for seqid in ORGAN_PROTEINS["Heart"]]
    rows.append({"seqid": ORGAN_PROTEINS["Kidney"][0]})
    return rows


def write_fixture(path: Path) -> None:
    lines = ["seqid"] + [row["seqid"] for row in fixture_rows()]
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def check_published_numbers():
    assert COHORT_N == 5676
    assert len(ORGAN_PROTEINS) == 11
    assert len(ORGAN_PROTEINS["Heart"]) == 10
    assert len(ORGAN_PROTEINS["Brain"]) == 202
    assert sum(len(proteins) for proteins in ORGAN_PROTEINS.values()) == 624
    assert ORGANISMAL_PROTEINS == 3907
    assert CONVENTIONAL_PROTEINS == 4778
    assert COGNITION_BRAIN_HR == 1.57
    heart = render_body(fixture_rows())
    assert "没有计算器官年龄" in heart[0][2]
    assert heart[1][0]["name"] == "心脏"
    assert "不是器官年龄" in heart[1][0]["detail"]
    names = [item["name"] for item in render_body(fixture_rows())[1]]
    assert names == ["心脏"]
